"""Fine-tune language models with adapters generated by quantum circuits."""

from __future__ import annotations

from quantum_adapter.config import QuantumAdapterConfig
from quantum_adapter.model import QuantumModel, get_quantum_model

__version__ = "0.1.0"
__all__ = ["QuantumAdapterConfig", "QuantumModel", "QuantumTrainer", "__version__", "get_quantum_model"]


def __getattr__(name: str):
    # Imported on first use, so `import quantum_adapter` doesn't pull in transformers.Trainer and accelerate.
    if name == "QuantumTrainer":
        from quantum_adapter.trainer import QuantumTrainer

        return QuantumTrainer
    raise AttributeError(f"module 'quantum_adapter' has no attribute {name!r}")
